import{_ as e,o as i,c as a,ai as t}from"./chunks/framework.Ba-VnP44.js";const b=JSON.parse('{"title":"工业物联网 IIoT · OpenBiz 第九个独立消费者（A 类收官）","description":"","frontmatter":{},"headers":[],"relativePath":"apps/openbiz/iiot.md","filePath":"apps/openbiz/iiot.md"}'),n={name:"apps/openbiz/iiot.md"};function c(d,o,r,p,s,l){return i(),a("div",null,[...o[0]||(o[0]=[t('<h1 id="工业物联网-iiot-·-openbiz-第九个独立消费者-a-类收官" tabindex="-1">工业物联网 IIoT · OpenBiz 第九个独立消费者（A 类收官） <a class="header-anchor" href="#工业物联网-iiot-·-openbiz-第九个独立消费者-a-类收官" aria-label="Permalink to “工业物联网 IIoT · OpenBiz 第九个独立消费者（A 类收官）”">​</a></h1><blockquote><p>现为独立应用 <code>openbiz-iiot-app</code>（<code>E:/8.cangku/for-job/openbiz-iiot-app</code>）：独立后端（端口 18089）+ 独立前端（Vue3/TS）+ 独立数据库 <code>openbiz_iiot</code>。</p></blockquote><blockquote><p><strong>当前状态</strong>：设备 + 告警双状态机已验证（16 步 E2E 全绿）；P0 采集链路已打通写入 → 缓存 → 查询（P0-01 数据层、P0-02 状态机、P0-03 契约收口、P0-04 点位、P0-05 攒批幂等写入、P0-06 最新值缓存、P0-07 降采样查询，均验收通过），<strong>并已完成 MQTT 接入与数据模拟器</strong>（P0-08 报文解析 + 订阅器 + 内嵌 broker、P0-14 直写 / 发报文双输出模拟器，34 项断言全绿），<strong>规则引擎已跑通告警闭环</strong>（P0-10 持续时长 + 迟滞恢复 + 收敛窗口，告警与通知 outbox 同事务，30 项断言全绿），<strong>通知派发已闭环</strong>（P0-11 outbox → 企微 webhook → 退避重试 → 死信，并回写告警通知状态，25 项断言全绿），<strong>长期运行能力已补齐</strong>（P0-12 按天分区自动补建与过期清理、5 分钟聚合只写已封口桶、按设备采集周期算阈值的心跳判活，38 项断言全绿），<strong>看板已上线</strong>（P0-13 首屏一个接口出状态灯/活动告警/关键点位，曲线内联 SVG 不引图表库，降级按数据年龄判定不白屏，27 项接口断言 + 11 个降级单测全绿），余 Modbus 接入。实施设计见工程仓库 <code>openbiz-iiot-app/docs/iiot-p0-design.md</code>。</p></blockquote><blockquote><p>实证：OpenBiz 母仓无 IIoT 域，按 OpenBiz 命名约定自建 <code>openbiz_iiot_*</code> 表，在其多租户基座之上实现「设备 + 告警双状态机 + 统计」最小闭环。<strong>这是 A 类 9 个系统中最后一个试水的，标志 A 类试水全覆盖完成。</strong></p></blockquote><h2 id="复用与自建" tabindex="-1">复用与自建 <a class="header-anchor" href="#复用与自建" aria-label="Permalink to “复用与自建”">​</a></h2><ul><li><strong>复用</strong>：OpenBiz <code>openbiz-saas-core</code> 多租户（TenantContext / TenantService / 自动装配）、RuoYi 登录外壳</li><li><strong>自建</strong>：<code>openbiz_iiot_device</code> / <code>openbiz_iiot_alarm</code> 表 + Mapper / Service / Controller <ul><li>设备状态机：<code>OFFLINE → ONLINE → FAULT → OFFLINE</code>，<code>ONLINE/FAULT → MAINTENANCE → OFFLINE</code>，<code>OFFLINE/ONLINE → DECOMMISSIONED</code>（不可逆终态）</li><li>告警状态机：<code>ACTIVE → ACKNOWLEDGED → RESOLVED</code>，<code>ACTIVE → CANCELLED</code></li></ul></li></ul><h2 id="业务闭环-e2e-已验证" tabindex="-1">业务闭环（E2E 已验证） <a class="header-anchor" href="#业务闭环-e2e-已验证" aria-label="Permalink to “业务闭环（E2E 已验证）”">​</a></h2><p>创建设备(<code>OFFLINE</code>) → 上线(<code>ONLINE</code>) → 建告警(<code>ACTIVE</code>) → 确认(<code>ACKNOWLEDGED</code>) → 解决(<code>RESOLVED</code>)；已解决再确认 / 取消均被 <code>ILLEGAL_TRANSITION</code> 拒绝。独立路径报故障(<code>FAULT</code>) → 维护(<code>MAINTENANCE</code>) → 结束维护(<code>OFFLINE</code>) → 再上线(<code>ONLINE</code>) → 退役(<code>DECOMMISSIONED</code>)；退役后再上线被拒。统计接口 <code>GET /api/iiot/stats</code> 返回设备 / 告警各状态数量。</p><h2 id="工程位置" tabindex="-1">工程位置 <a class="header-anchor" href="#工程位置" aria-label="Permalink to “工程位置”">​</a></h2><p><code>E:/8.cangku/for-job/openbiz-iiot-app</code>（含 README 与 E2E 脚本，端口 18089）</p><h2 id="价值" tabindex="-1">价值 <a class="header-anchor" href="#价值" aria-label="Permalink to “价值”">​</a></h2><p>与工单 / MES / PMS / CRM / ERP / OA / BPM 等共同坐实「百套流水线」可复制。EAM 已下线，仓储场景改由规划中的 WMS 承接；当前 OpenBiz 已交付 <strong>10</strong> 个独立应用（含本 IIoT）。</p><h2 id="下一步-p0" tabindex="-1">下一步（P0） <a class="header-anchor" href="#下一步-p0" aria-label="Permalink to “下一步（P0）”">​</a></h2><p>从「状态机 Demo」推进到「可连真设备演示」，P0 只补三件事：<strong>采得上</strong>（MQTT 订阅 + Modbus TCP 轮询，收敛到统一 <code>Sample</code>）、<strong>存得下</strong>（MySQL 分区明细 + 5 分钟聚合，幂等批量写入）、<strong>报得准</strong>（阈值 + 持续时长 + 迟滞恢复 + 收敛窗口）。</p><p>明确不做：Modbus RTU、OPC-UA/S7、TDengine、动态阈值、设备影子与 OTA —— 这些归 P1/P2，P0 不碰。完整表结构、接口契约、任务拆解与 16 条验收用例见工程仓库 <code>openbiz-iiot-app/docs/iiot-p0-design.md</code>（实施文档不发布到站点）。</p><hr><p>上一级：<a href="/my-vitepress-site/apps/openbiz/">OpenBiz 试水实证</a></p>',17)])])}const h=e(n,[["render",c]]);export{b as __pageData,h as default};
